def _calc_lines(c, mode):
    out = []
    for j, ln in enumerate(c):
        t = ln.strip()
        m = re.match(r'^([A-Za-z]\w*)\s*=(.*)$', t)
        if m:
            idu, rest = m.group(1), m.group(2).strip()
            rhs = process(rest, mode)
            if j == len(c) - 1 and '[[' not in rest:
                rhs = f'<span class="res">{rhs}</span>'
            out.append(f'<span class="id">{html.escape(idu)}</span> = {rhs}')
        else:
            out.append(process(t, mode))
    return '<br>'.join(out)

def render_example(btitle, bbody, mode):
    calcs, cur = [], []
    for l in bbody:
        if l.strip() == "":
            if cur: calcs.append(cur); cur = []
        else:
            cur.append(l)
    if cur: calcs.append(cur)
    cells = "".join(f'<div class="calc">{_calc_lines(c, mode)}</div>' for c in calcs)
    return (f'<div class="ex"><span class="exlab">{inline(btitle or "Exemples")}&nbsp;:</span>'
            f'<div class="calcs">{cells}</div></div>')

