def mathalea_title_from_url(url):
    """Retourne un intitulé lisible à partir d'une URL MathALÉA.
    On utilise le paramètre ?id=... ; si l'id n'est pas connu, on donne un libellé stable.
    """
    try:
        q = parse_qs(urlparse(url).query)
        ex_id = (q.get("id") or [""])[0]
    except Exception:
        ex_id = ""
    if ex_id in MATHALEA_TITLES:
        return MATHALEA_TITLES[ex_id]
    if ex_id:
        return f"Exercice MathALÉA {ex_id}"
    return "Exercice MathALÉA"


