def sticker_img(key, cls="sticker"):
    src = _img_b64(STICKERS.get(key, ""))
    return f'<img class="{cls}" src="{src}" alt=""/>' if src else ""

def split_label_url(line):
    """Accepte :
      - Libellé : https://...
      - Libellé | https://...
      - https://...
    Retourne (libellé, url).
    """
    line = line.strip().lstrip("- ").strip()
    if "|" in line:
        lab, url = line.split("|", 1)
        url = url.strip()
        return lab.strip() or mathalea_title_from_url(url), url
    m = URL_RE.search(line)
    if not m:
        return line, ""
    url = m.group(0).rstrip(").,; ")
    before = line[:m.start()].strip(" :–—-")
    return (before or mathalea_title_from_url(url)), url

def render_raw(btitle, bbody, mode):
    return "\n".join(bbody)

def render_reussite(btitle, bbody, mode):
    items = "".join(f'<div class="rchk"><span class="rbox"></span>{process(l.strip(), mode)}</div>'
                    for l in bbody if l.strip())
    return (f'<div class="box reussite has-sticker"><span class="lab">{html.escape(btitle or "Critères de réussite")}</span>'
            f'{sticker_img("reussite")}<div class="box-content">{items}</div></div>')

def render_ressources(btitle, bbody, mode):
    items = []
    for l in bbody:
        ls = l.strip()
        if not ls or not (ls.startswith("- ") or URL_RE.search(ls)):
            continue
        lab, url = split_label_url(ls)
        qr = make_qr(url) if url else ""
        items.append(f'<li><span class="res-txt">{inline(lab)}<br>'
                     f'<span class="res-url">{link_to(url, url)}</span></span>{qr}</li>')
    return (f'<div class="box plus"><span class="lab">{html.escape(btitle or "Pour aller plus loin")}</span>'
            f'<ul class="ressources">{"".join(items)}</ul></div>')

def render_video(btitle, bbody, mode):
    raw = "\n".join(x.strip() for x in bbody if x.strip())
    m = URL_RE.search(raw)
    if not m:
        return f'<div class="box video"><span class="lab">Vidéo</span>{lines_html(bbody, mode)}</div>'
    url = m.group(0).rstrip(").,; ")
    note = (raw[:m.start()] + raw[m.end():]).strip()
    title = btitle or "Vidéo d’explication"
    note_html = f'<p class="qr-note">{process(note, mode)}</p>' if note else '<p class="qr-note">Scanne pour revoir cette notion.</p>'
    return (f'<div class="box video qrbox"><span class="lab">{inline(title)}</span>'
            f'<div class="qr-main"><div class="qr-text">{note_html}'
            f'<div class="tap-hint">Scanner ou cliquer pour ouvrir.</div></div><div class="qr-side">{make_qr(url)}</div></div></div>')

def render_defi(btitle, bbody, mode):
    """Petit défi de fin de chapitre, dans l'esprit du cahier de vacances."""
    title = btitle or "★★★ Défi du chapitre"
    content = lines_html(bbody, mode)
    return (f'<div class="box defi has-sticker"><span class="lab">{inline(title)}</span>'
            f'{sticker_img("defi", "sticker defi-sticker")}<div class="defi-content">{content}</div>'
            f'<div class="scratch-title">✎ BROUILLON</div><div class="scratch-zone"></div></div>')

def render_auto_defi(code, title, mode):
    txt = AUTO_DEFIS.get(code) or AUTO_DEFIS.get(code.upper())
    if not txt:
        return ""
    return render_defi("★★★ Défi du chapitre", [txt], mode)


def body_has_box(body, *names):
    wanted = set(names)
    return any(kind == "box" and data[0] in wanted for kind, data in body)

def render_mathalea(btitle, bbody, mode):
    entries = []
    for l in bbody:
        ls = l.strip()
        if not ls:
            continue
        lab, url = split_label_url(ls)
        if url:
            entries.append((lab, url))
    if not entries:
        return f'<div class="box mathalea"><span class="lab">MathALÉA</span>{lines_html(bbody, mode)}</div>'

    # Si une page-hub de chapitre est fournie, on privilégie un seul QR :
    # plus lisible sur le livret papier, et plus cohérent avec l'usage iPad.
    if HUB_URL:
        title = btitle or "Je m’entraîne"
        count = len(entries)
        detail = " · ".join(html.escape(lab) for lab, _ in entries[:3])
        if count > 3:
            detail += f" · + {count-3} autre(s)"
        return (f'<div class="box mathalea qrbox has-sticker"><span class="lab">{inline(title)}</span>'
                f'{sticker_img("mathalea")}<div class="qr-main"><div class="qr-text">'
                f'<p class="qr-note"><strong>Exercices interactifs du chapitre.</strong></p>'
                f'<p class="qr-detail">{detail}</p>'
                f'<div class="tap-hint">Scanner ou cliquer pour ouvrir la page N1.</div></div>'
                f'<div class="qr-side">{make_qr(HUB_URL)}</div></div></div>')

    # Sinon, on conserve le comportement détaillé : un QR par lien MathALÉA.
    rows = "".join(
        f'<div class="ma-cell"><span class="ma-title">{inline(lab)}</span>'
        f'<span class="ma-qr">{make_qr(url)}</span></div>'
        for lab, url in entries
    )
    return (f'<div class="box mathalea"><span class="lab">{inline(btitle or "Je m’entraîne")}</span>'
            f'<div class="mathalea-grid">{rows}</div></div>')

def render_standard_box(btype, btitle, bbody, mode):
    cls, deflabel = BOXMAP.get(btype, ("rem", btype.capitalize()))
    label = btitle or deflabel
    st = sticker_img(btype) if btype in ("rappel", "retenu") else ""
    has = " has-sticker" if st else ""
    return f'<div class="box {cls}{has}"><span class="lab">{inline(label)}</span>{st}{lines_html(bbody, mode)}</div>'

BOX_RENDERERS = {
    "raw": render_raw,
    "exemple": lambda t, b, m: render_example(t, b, m),
    "exemples": lambda t, b, m: render_example(t, b, m),
    "ex": lambda t, b, m: render_example(t, b, m),
    "reussite": render_reussite,
    "ressources": render_ressources,
    "video": render_video,
    "mathalea": render_mathalea,
    "defi": render_defi,
}

def render_box(btype, btitle, bbody, mode):
    renderer = BOX_RENDERERS.get(btype)
    if renderer:
        return renderer(btitle, bbody, mode)
    return render_standard_box(btype, btitle, bbody, mode)

def render_body(body, mode):
    parts, secn = [], 0
    for kind, data in body:
        if kind == "section":
            secn += 1
            t = data.strip()
            mm = re.match(r'^([IVXLC]+|[A-Z])[.)]\s*(.+)$', t)
            num = str(secn)  # numérotation classique 1,2,3
            ttl = mm.group(2) if mm else t
            parts.append(f'<div class="sec"><span class="n">{num}</span><h2>{inline(ttl)}</h2></div>')
        elif kind == "para":
            parts.append(lines_html(data, mode))
        elif kind == "box":
            btype, btitle, bbody = data
            parts.append(render_box(btype, btitle, bbody, mode))
    return "\n".join(parts)

def split_chapters(blocks):
    cover, chaps, cur = None, [], None
    for kind, data in blocks:
        if kind == "box" and data[0] == "couverture":
            cover = parse_cover(data[2]); continue
        if kind == "header":
            cur = {"header": data, "body": []}; chaps.append(cur)
        elif cur is not None:
            cur["body"].append((kind, data))
    return cover, chaps

