def render_objectifs_vises(seq, mode):
    objs = seq.get("objectifs", []) or []
    if not objs: return ""
    lis = "".join(f'<li>{_niv_badge(o.get("niveau","")) if mode!="eleve" else ""}{inline(o.get("texte",""))}</li>' for o in objs)
    return ('<div class="box objectifs"><span class="lab">Objectifs visés</span>'
            "<p class=\"obj-intro\">Dans ce chapitre, j'apprends à&nbsp;:</p>"
            f'<ul class="obj-list">{lis}</ul></div>')
def render_capable(seq, mode):
    objs = seq.get("objectifs", []) or []
    if not objs: return ""
    qrcol = any(EXOMAP.get(o.get("code")) for o in objs)
    extra = '<th class="cap-exo">Pour m\'entraîner</th>' if qrcol else ''
    head = (f'<tr><th class="cap-obj">Objectif</th><th>{FACE["no"]}<br><span class="cap-h">je plante</span></th>'
            f'<th>{FACE["mid"]}<br><span class="cap-h">je progresse</span></th>'
            f'<th>{FACE["ok"]}<br><span class="cap-h">je maîtrise</span></th>{extra}</tr>')
    rows = []
    for o in objs:
        url = EXOMAP.get(o.get("code"))
        cell = (f'<td class="cap-exo">{make_qr(url)}</td>' if url else '<td class="cap-exo"></td>') if qrcol else ''
        rows.append(f'<tr><td class="cap-obj">{_niv_badge(o.get("niveau","")) if mode!="eleve" else ""}{inline(o.get("texte",""))}</td>'
                    f'<td class="cap-tick"></td><td class="cap-tick"></td><td class="cap-tick"></td>{cell}</tr>')
    return ('<div class="capable"><div class="cap-title">Je suis maintenant capable de&nbsp;…</div>'
            f'<table class="capgrid">{head}{"".join(rows)}</table>'
            '<div class="cap-note">Je mets une croix dans la case qui me correspond pour chaque objectif.</div></div>')

def render(blocks, mode):
    cover, chaps = split_chapters(blocks)
    parts = []
    if cover: parts.append(render_cover(cover, mode))
    for i, ch in enumerate(chaps):
        code, title, niveau, comp = ch["header"]
        th, thd = DOMAIN_TH.get(code[:1].upper(), DOMAIN_TH["N"])
        brk = "chap-break" if i > 0 else ""
        parts.append(f'<div class="chapitre {brk}" style="--th:{th};--thd:{thd}">')
        parts.append(chap_header(code, title, niveau))
        parts.append(render_comp(comp))
        seqp = PONT.get(code) or PONT.get(code.upper())
        if seqp: parts.append(render_objectifs_vises(seqp, mode))
        parts.append(render_body(ch["body"], mode))
        if seqp: parts.append(render_capable(seqp, mode))
        if not body_has_box(ch["body"], "defi"):
            parts.append(render_auto_defi(code, title, mode))
        parts.append("</div>")
    return "\n".join(parts)

