def font_faces_file():
    def ff(fam, wght, style, fn):
        p = FONT_DIR / fn
        if not p.exists(): return ""
        st = f"font-style:{style};" if style else ""
        return f"@font-face{{font-family:'{fam}';font-weight:{wght};{st}src:url('{p.as_uri()}');}}\n"
    return ("".join([
        ff("Round","300 700","","Baloo2.ttf"),
        ff("TitleC","200 700","","Oswald-VF.ttf"),
        ff("Body","300 800","","OpenSans-VF.ttf"),
        ff("Body","300 800","italic","OpenSans-Italic-VF.ttf"),
        ff("MathVar","400","italic","KaTeX_Math-Italic.ttf"),
        ff("Atkinson","400","","Atkinson-Regular.ttf"), ff("Atkinson","700","","Atkinson-Bold.ttf"),
        ff("Atkinson","400","italic","Atkinson-Italic.ttf"), ff("Atkinson","700","italic","Atkinson-BoldItalic.ttf"),
        ff("OpenDyslexic","400","","OpenDyslexic-Regular.otf"), ff("OpenDyslexic","700","","OpenDyslexic-Bold.otf"),
        ff("OpenDyslexic","400","italic","OpenDyslexic-Italic.otf"),
    ]))

def font_faces_b64(police="atkinson"):
    import base64 as _b64
    def ff(fam, wght, style, fn):
        if fn in EMBEDDED_FONTS:
            data = EMBEDDED_FONTS[fn]
        else:
            p = FONT_DIR / fn
            if not p.exists(): return ""
            data = _b64.b64encode(p.read_bytes()).decode()
        mime = "font/otf" if fn.lower().endswith(".otf") else "font/ttf"
        st = f"font-style:{style};" if style else ""
        return f"@font-face{{font-family:'{fam}';font-weight:{wght};{st}src:url('data:{mime};base64,{data}');}}\n"
    out = [ff("MathVar","400","italic","KaTeX_Math-Italic.ttf")]
    for w in ("400","500","600","700"):
        out.append(ff("Round",w,"","Baloo2-s.ttf"))
        out.append(ff("TitleC",w,"","Oswald-s.ttf"))
    if police == "atkinson":
        out += [ff("Atkinson","400","","Atkinson-Regular.ttf"), ff("Atkinson","700","","Atkinson-Bold.ttf"),
                ff("Atkinson","400","italic","Atkinson-Italic.ttf"), ff("Atkinson","700","italic","Atkinson-BoldItalic.ttf")]
    elif police == "opendyslexic":
        out += [ff("OpenDyslexic","400","","OpenDyslexic-Regular.otf"), ff("OpenDyslexic","700","","OpenDyslexic-Bold.otf"),
                ff("OpenDyslexic","400","italic","OpenDyslexic-Italic.otf")]
    else:
        for w in ("300","400","500"): out.append(ff("Body",w,"","OpenSans-s.ttf"))
        for w in ("600","700","800"): out.append(ff("Body",w,"","OpenSans-b.ttf"))
        out.append(ff("Body","400","italic","OpenSans-it.ttf"))
    return "".join(out)

