# ============================================================ DOC
def html_doc(body, css, web=False):
    wo, wc = ('<div class="wrap">', '</div>') if web else ('', '')
    return (f"<!DOCTYPE html><html lang='fr'><head><meta charset='utf-8'>"
            f"<meta name='viewport' content='width=device-width, initial-scale=1'>"
            f"<style>{css}</style></head><body>{wo}{body}{wc}</body></html>")

# ============================================================ SÉLECTEUR (builder)
def build_builder(blocks, outdir, stem, cover_meta_master):
    cover, chaps = split_chapters(blocks)
    cover = cover or cover_meta_master or {}
    data = []
    for ch in chaps:
        code, title, niveau, comp = ch["header"]
        theme = THEME.get(code[:1].upper(), THEME["N"])
        comps = [{"c": c.strip(), "l": COMP_MAP.get(c.strip(), "")} for c in comp.split(",") if c.strip()]
        frag = (f'<div class="chapitre" style="--c:{theme}">'
                f'{bandeau_html(code, title, niveau)}{render_comp(comp)}'
                f'{render_body(ch["body"], "inter")}</div>')
        data.append({"code": code, "title": title, "niveau": niveau or cover.get("niveau", "4ᵉ"),
                     "theme": theme, "comps": comps, "html": frag})
    css = (font_faces_file() + CHARTER_CSS.replace("@@SIZE@@","12").replace("@@LH@@","1.5").replace("@@REP@@","#c0698e") + cover_css(False) + cover_vacances_css())
    tmpl = BUILDER_TMPL
    repl = {
        "__CSS__": css,
        "__CHAPTERS__": json.dumps(data, ensure_ascii=False),
        "__FOX__": json.dumps(fox_svg()),
        "__TITRE__": json.dumps(cover.get("titre", "Cahier de cours")),
        "__MATIERE__": json.dumps(cover.get("matiere", "Mathématiques")),
        "__NIVEAU__": json.dumps(cover.get("niveau", "4ᵉ")),
        "__PERIODE__": json.dumps(cover.get("periode", "Période ")),
        "__ANNEE__": json.dumps(cover.get("annee", "2025 – 2026")),
        "__PROF__": json.dumps(cover.get("prof", "Mme Le Guern")),
    }
    for k, v in repl.items():
        tmpl = tmpl.replace(k, v)
    out = outdir / f"{stem}__selecteur.html"
    out.write_text(tmpl, encoding="utf-8")
    print(f"  ✓ {out.name}")
    return out

BUILDER_TMPL = r"""<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sélecteur de livret</title>
<style>
__CSS__
:root{--ff:"Atkinson",sans-serif;--fs:12pt;}
*{box-sizing:border-box;}
body{margin:0;font-family:"Atkinson",sans-serif;background:#eef0f6;color:#222;}
.app{display:grid;grid-template-columns:300px 1fr;min-height:100vh;}
.panel{background:#fff;border-right:1px solid #dde;padding:16px;overflow:auto;position:sticky;top:0;height:100vh;}
.panel h1{font-size:17px;margin:0 0 12px;color:#2E5E8C;}
.panel h2{font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#889;border:0;margin:16px 0 6px;}
.field{margin:8px 0;} .field label{display:block;font-size:13px;color:#445;margin-bottom:3px;}
.field input,.field select{width:100%;padding:6px 8px;border:1px solid #ccd;border-radius:8px;font:inherit;}
.chaplist{list-style:none;margin:0;padding:0;}
.chaprow{display:flex;align-items:center;gap:7px;padding:6px 7px;border:1px solid #e3e6f0;border-radius:9px;margin:5px 0;background:#fafbff;}
.chaprow input{margin:0;} .chaprow .cc{font-weight:bold;min-width:26px;color:#3B82C4;}
.chaprow .ct{flex:1;font-size:13px;} .chaprow .mv{display:flex;flex-direction:column;gap:1px;}
.chaprow .mv button{border:1px solid #ccd;background:#fff;border-radius:5px;cursor:pointer;line-height:1;padding:0 5px;font-size:11px;}
.seg{display:flex;gap:0;border:1px solid #ccd;border-radius:9px;overflow:hidden;}
.seg button{flex:1;border:0;background:#fff;padding:7px;cursor:pointer;font:inherit;}
.seg button.on{background:#3B82C4;color:#fff;}
.btn{display:block;width:100%;margin:7px 0;padding:9px;border:0;border-radius:10px;background:#2E5E8C;color:#fff;font:inherit;cursor:pointer;}
.btn.alt{background:#5a8f6f;} .btn.ghost{background:#eef;color:#2E5E8C;}
.stagewrap{padding:24px;overflow:auto;}
.stage{max-width:820px;margin:0 auto;background:#fff;box-shadow:0 6px 30px rgba(80,80,140,.12);border-radius:10px;padding:26px 30px;font-family:var(--ff);font-size:var(--fs);line-height:1.5;}
.stage.mode-prof .ans{color:#c0392b;font-weight:600;}
.stage.mode-prof .cover-id{display:none;}
.stage.mode-eleve .ans{color:transparent;border-bottom:1.4px dotted #555;}
.hint{font-size:12px;color:#889;margin-top:4px;}
@media print{
  .panel{display:none;} .app{display:block;} .stagewrap{padding:0;}
  .stage{box-shadow:none;border-radius:0;max-width:none;padding:0;}
  .chapitre{break-before:page;page-break-before:always;} .chapitre:first-of-type{break-before:auto;}
  .cover{break-after:page;} @page{size:A4 portrait;margin:14mm 15mm;}
  body{background:#fff;}
}
</style></head>
<body>
<div class="app">
  <div class="panel">
    <h1>🦊 Sélecteur de livret</h1>
    <div class="field"><label>Période (titre)</label><input id="periode"></div>
    <div class="field"><label>Niveau</label><input id="niveau"></div>
    <div class="field"><label>Année</label><input id="annee"></div>

    <h2>Chapitres (ordre = livret)</h2>
    <ul class="chaplist" id="chaplist"></ul>

    <h2>Affichage</h2>
    <div class="field"><label>Version</label>
      <div class="seg" id="seg-mode">
        <button data-v="eleve" class="on">Élève</button><button data-v="prof">Prof</button></div></div>
    <div class="field"><label>Police</label>
      <select id="police"><option value="atkinson">Atkinson Hyperlegible</option>
      <option value="opendyslexic">OpenDyslexic</option></select></div>
    <div class="field"><label>Taille</label>
      <select id="taille"><option>11</option><option selected>12</option><option>13</option><option>14</option></select></div>

    <h2>Exporter</h2>
    <button class="btn" onclick="printPDF()">🖨️ Imprimer / PDF</button>
    <button class="btn alt" onclick="downloadHTML()">⬇️ Télécharger HTML</button>
    <button class="btn ghost" onclick="exportManifest()">📄 Manifeste .txt (pour le script)</button>
    <p class="hint">Pour le PDF : « Enregistrer en PDF », marges « par défaut », cocher les graphiques d'arrière-plan.</p>
  </div>

  <div class="stagewrap"><div class="stage mode-eleve" id="stage"></div></div>
</div>

<script>
const CHAPTERS = __CHAPTERS__;
const FOX = __FOX__;
const META = {titre:__TITRE__, matiere:__MATIERE__, niveau:__NIVEAU__,
              periode:__PERIODE__, annee:__ANNEE__, prof:__PROF__};
const FONTSTACK = {atkinson:'"Atkinson", sans-serif', opendyslexic:'"OpenDyslexic", sans-serif'};

let order = CHAPTERS.map((_,i)=>i);
let selected = new Set(order);

function esc(s){return (s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;");}

function coverHTML(){
  const chosen = order.filter(i=>selected.has(i));
  const somm = chosen.map(i=>{
    const c=CHAPTERS[i];
    return `<li><span class="case-somm"></span><span class="c-code">${esc(c.code)}</span><span class="c-titre">${esc(c.title)}</span></li>`;
  }).join("");
  return `<section class="cover"><div class="cover-corner tl"></div><div class="cover-corner br"></div>
    <div class="cover-id"><div class="idbox"><b>NOM :</b> ………………………<br><b>PRÉNOM :</b> ………………………</div>
    <div class="idbox"><b>CLASSE :</b> …………………</div></div>
    <h1 class="cover-title">${esc(META.titre)}</h1>
    <div class="cover-sub">${esc(META.matiere)} <span class="lvl">${esc(document.getElementById('niveau').value||META.niveau)}</span></div>
    ${FOX}
    <div class="cover-periode"><div class="periode-label">${esc(document.getElementById('periode').value||META.periode)}</div>
    <ul class="sommaire">${somm}</ul></div>
    <div class="cover-foot"><span class="prof">${esc(META.prof)}</span><span class="annee">${esc(document.getElementById('annee').value||META.annee)}</span></div></section>`;
}

function renderPreview(){
  const stage = document.getElementById('stage');
  const chosen = order.filter(i=>selected.has(i));
  stage.innerHTML = coverHTML() + chosen.map(i=>CHAPTERS[i].html).join("");
  const mode = document.querySelector('#seg-mode .on').dataset.v;
  stage.className = "stage mode-"+mode;
  stage.style.setProperty('--ff', FONTSTACK[document.getElementById('police').value]);
  stage.style.setProperty('--fs', document.getElementById('taille').value+'pt');
}

function renderList(){
  const ul = document.getElementById('chaplist'); ul.innerHTML="";
  order.forEach((idx,pos)=>{
    const c = CHAPTERS[idx];
    const li = document.createElement('li'); li.className="chaprow";
    li.innerHTML = `<input type="checkbox" ${selected.has(idx)?'checked':''}>
      <span class="cc">${esc(c.code)}</span><span class="ct">${esc(c.title)}</span>
      <span class="mv"><button data-d="-1">▲</button><button data-d="1">▼</button></span>`;
    li.querySelector('input').onchange = e=>{ e.target.checked?selected.add(idx):selected.delete(idx); renderPreview(); };
    li.querySelectorAll('.mv button').forEach(b=> b.onclick=()=>{
      const np = pos + (+b.dataset.d);
      if(np<0||np>=order.length) return;
      [order[pos],order[np]]=[order[np],order[pos]]; renderList(); renderPreview();
    });
    ul.appendChild(li);
  });
}

document.querySelectorAll('#seg-mode button').forEach(b=> b.onclick=()=>{
  document.querySelectorAll('#seg-mode button').forEach(x=>x.classList.remove('on'));
  b.classList.add('on'); renderPreview();
});
['periode','niveau','annee','police','taille'].forEach(id=>
  document.getElementById(id).addEventListener('input', renderPreview));

function fullCSS(){ return document.querySelector('style').textContent; }

function downloadHTML(){
  const mode = document.querySelector('#seg-mode .on').dataset.v;
  const ff = FONTSTACK[document.getElementById('police').value];
  const fs = document.getElementById('taille').value+'pt';
  const content = document.getElementById('stage').innerHTML;
  const doc = `<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><title>Livret</title>
<style>${fullCSS()}
body{margin:0;background:#fff;}
.stage{max-width:820px;margin:0 auto;padding:22px;font-family:${ff};font-size:${fs};line-height:1.5;}
.stage.mode-prof .ans{color:#c0392b;font-weight:600;}
.stage.mode-prof .cover-id{display:none;}
.stage.mode-eleve .ans{color:transparent;border-bottom:1.4px dotted #555;}
.tgl{position:fixed;top:10px;right:10px;z-index:9;}
.tgl button{border:1px solid #ccd;background:#fff;border-radius:8px;padding:6px 10px;cursor:pointer;}
@media print{.tgl{display:none;}.chapitre{break-before:page;}.chapitre:first-of-type{break-before:auto;}.cover{break-after:page;}@page{size:A4;margin:14mm 15mm;}}
</style></head><body>
<div class="tgl"><button onclick="t()">Prof / Élève</button></div>
<div class="stage mode-${mode}" id="s">${content}</div>
<script>function t(){var s=document.getElementById('s');s.classList.toggle('mode-prof');s.classList.toggle('mode-eleve');}<\/script>
</body></html>`;
  const blob = new Blob([doc],{type:'text/html'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download = 'Livret-'+(document.getElementById('periode').value||'export').replace(/\s+/g,'_')+'.html'; a.click();
}

function exportManifest(){
  const chosen = order.filter(i=>selected.has(i));
  let txt = ":::couverture\n";
  txt += "titre: "+META.titre+"\nmatiere: "+META.matiere+"\nniveau: "+(document.getElementById('niveau').value||META.niveau)+"\n";
  txt += "periode: "+(document.getElementById('periode').value||META.periode)+"\nannee: "+(document.getElementById('annee').value||META.annee)+"\nprof: "+META.prof+"\nchapitres:\n";
  chosen.forEach(i=> txt += "- "+CHAPTERS[i].code+" | "+CHAPTERS[i].title+"\n");
  txt += ":::\n\n";
  chosen.forEach(i=> txt += "@include "+CHAPTERS[i].code+".txt\n");
  const blob = new Blob([txt],{type:'text/plain'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='periode.txt'; a.click();
}

function printPDF(){ window.print(); }

// init
document.getElementById('periode').value = META.periode;
document.getElementById('niveau').value = META.niveau;
document.getElementById('annee').value = META.annee;
renderList(); renderPreview();
</script>
</body></html>"""


# ============================================================ QCM / KAHOOT
from urllib.parse import urlparse, parse_qs
import random, zipfile

def _clean_url(u):
    return u.strip().rstrip(').,;')

def extract_mathalea_entries(blocks):
    """Extrait les lignes :::mathalea du Markdown."""
    entries = []
    _cover, chaps = split_chapters(blocks)
    for ch in chaps:
        code = ch['header'][0]
        for kind, data in ch['body']:
            if kind != 'box':
                continue
            btype, btitle, bbody = data
            if btype != 'mathalea':
                continue
            for line in bbody:
                ls = line.strip()
                if not ls:
                    continue
                lab, url = split_label_url(ls)
                if not url:
                    continue
                q = parse_qs(urlparse(url).query)
                ex_id = (q.get('id') or [''])[0]
                entries.append({'chapitre': code, 'label': lab or ex_id or 'Exercice MathALÉA', 'url': _clean_url(url), 'exo_id': ex_id})
    return entries

def _fmt(n):
    return f'({n})' if n < 0 else str(n)

def _unique_choices(correct, candidates):
    vals = []
    for v in [correct] + candidates:
        if v not in vals:
            vals.append(v)
    k = 1
    while len(vals) < 4:
        for v in (correct+k, correct-k, -correct+k):
            if v not in vals:
                vals.append(v)
                if len(vals) == 4:
                    break
        k += 1
    return vals[:4]

def _mk_question(qid, chapitre, source, question, correct, distractors, explication, temps=20):
    nums = _unique_choices(correct, distractors)
    rng = random.Random(qid)
    rng.shuffle(nums)
    good = nums.index(correct)
    return {
        'id': qid,
        'niveau': '4e',
        'chapitre': chapitre,
        'source': 'mathalea',
        'lien': source.get('url', ''),
        'type': 'quiz',
        'question': question,
        'choix': [str(x) for x in nums],
        'bonnesReponses': [good],
        'explication': explication,
        'temps': temps,
    }

def gen_additions(entry, n=6):
    pairs = [(-7,-5), (-8,3), (12,-17), (-4,9), (6,-2), (-11,11), (7,8), (-13,-4)]
    qs=[]
    for i,(a,b) in enumerate(pairs[:n],1):
        c=a+b
        same = (a>=0 and b>=0) or (a<0 and b<0)
        exp = 'Même signe : on garde le signe et on additionne les distances.' if same else 'Signes contraires : on soustrait les distances et on garde le signe du plus éloigné de 0.'
        qs.append(_mk_question(f"{entry['chapitre']}-{entry['exo_id']}-{i:02d}", entry['chapitre'], entry, f"Calcule : {_fmt(a)} + {_fmt(b)}", c, [-c, a-b, b-a, abs(a)+abs(b)], exp))
    return qs

def gen_soustractions(entry, n=6):
    pairs = [(-12,-2), (15,13), (2,16), (-5,7), (9,-4), (-8,-11), (6,-10)]
    qs=[]
    for i,(a,b) in enumerate(pairs[:n],1):
        c=a-b
        qs.append(_mk_question(f"{entry['chapitre']}-{entry['exo_id']}-{i:02d}", entry['chapitre'], entry, f"Calcule : {_fmt(a)} - {_fmt(b)}", c, [-c, a+b, b-a, abs(a)-abs(b)], 'Soustraire un nombre revient à ajouter son opposé.'))
    return qs

def gen_enchainements(entry, n=6):
    exprs = [[-1,3,7,-2,-5,-4], [2,5,-6,-4], [5,18,-14,3,-9], [-5,8,-2], [-6,4,-3,9], [10,-7,-8,2]]
    qs=[]
    for i,vals in enumerate(exprs[:n],1):
        c=sum(vals)
        text = ' + '.join(_fmt(v) for v in vals).replace('+ (-','- (')
        qs.append(_mk_question(f"{entry['chapitre']}-{entry['exo_id']}-{i:02d}", entry['chapitre'], entry, f"Calcule : {text}", c, [-c, sum(abs(v) for v in vals), c+2, c-2], 'On regroupe les nombres positifs et les nombres négatifs, puis on calcule.'))
    return qs

def gen_multi_add(entry, n=6):
    exprs = [[-3,-5,-2], [4,-9,2], [-7,12,-5], [8,-3,-6], [-10,4,6], [2,-8,-7]]
    qs=[]
    for i,vals in enumerate(exprs[:n],1):
        c=sum(vals)
        text = ' + '.join(_fmt(v) for v in vals).replace('+ (-','- (')
        qs.append(_mk_question(f"{entry['chapitre']}-{entry['exo_id']}-{i:02d}", entry['chapitre'], entry, f"Calcule : {text}", c, [-c, c+1, c-1, sum(abs(v) for v in vals)], 'On peut additionner dans l’ordre que l’on veut en regroupant les signes.'))
    return qs

def generate_qcm_from_mathalea(blocks, per_link=6):
    questions=[]
    for e in extract_mathalea_entries(blocks):
        ex=e['exo_id']
        if ex == '5R20':
            questions += gen_additions(e, per_link)
        elif ex == '5R21':
            questions += gen_soustractions(e, per_link)
        elif ex == '5R22':
            questions += gen_enchainements(e, per_link)
        elif ex == '5R20-6':
            questions += gen_multi_add(e, per_link)
        else:
            questions += gen_additions(e, min(3, per_link))
    return questions

def export_questions_js(path, questions, varname='QUESTIONS_4EME'):
    p = Path(path)
    block = ("\n// ===== AUTO-GÉNÉRÉ PAR build_livret_v5.py : début =====\n" +
             f"window.{varname} = window.{varname} || [];\n" +
             f"window.{varname}.push(..." + json.dumps(questions, ensure_ascii=False, indent=2) + ");\n" +
             "// ===== AUTO-GÉNÉRÉ PAR build_livret_v5.py : fin =====\n")
    if p.exists():
        old = p.read_text(encoding='utf-8')
        pat = re.compile(r"\n// ===== AUTO-GÉNÉRÉ PAR build_livret_v5\.py : début =====.*?// ===== AUTO-GÉNÉRÉ PAR build_livret_v5\.py : fin =====\n", re.S)
        txt = pat.sub(block, old) if pat.search(old) else old.rstrip() + "\n" + block
    else:
        txt = block.lstrip()
    p.write_text(txt, encoding='utf-8')

QCM_HTML = """<!DOCTYPE html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>QCM 4e — entraînement</title><style>body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#f6f0fb;color:#4a4458;margin:0;padding:20px}.app{max-width:900px;margin:auto;background:white;border-radius:22px;padding:24px;box-shadow:0 12px 30px #7d54a322}h1{color:#3f78a3}select,button{font:inherit;border-radius:12px;border:1px solid #d8c8e6;padding:9px 12px;margin:4px}button{background:#3f78a3;color:white;border:0;cursor:pointer}.card{border:2px solid #d8c8e6;border-radius:18px;padding:16px;margin-top:18px}.choices{display:grid;gap:10px;margin-top:12px}.choice{background:#faf7fc;border:1px solid #eadff2;border-radius:14px;padding:12px;text-align:left;color:#4a4458}.choice.ok{background:#ecfdf3;border-color:#5fb98c}.choice.bad{background:#fff0f3;border-color:#c0537a}.meta{color:#8a7ea0;font-size:.9em}.exp{margin-top:12px;background:#fff8ea;border-left:5px solid #e6b450;padding:10px;border-radius:12px}.hidden{display:none}</style></head><body><div class=\"app\"><h1>QCM 4e — entraînement</h1><p>Choisis un chapitre, puis réponds aux questions générées depuis les liens MathALÉA.</p><label>Chapitre <select id=\"chap\"></select></label><button id=\"new\">Nouvelle question</button><div id=\"card\" class=\"card\"></div></div><script src=\"questions.js\"></script><script>const QS=(window.QUESTIONS_4EME||[]);const chap=document.getElementById('chap'),card=document.getElementById('card');[...new Set(QS.map(q=>q.chapitre))].forEach(c=>{let o=document.createElement('option');o.value=c;o.textContent=c;chap.appendChild(o)});let current=null;function pick(){let arr=QS.filter(q=>q.chapitre===chap.value);current=arr[Math.floor(Math.random()*arr.length)];render()}function render(){if(!current){card.textContent='Aucune question.';return}card.innerHTML=`<div class=\"meta\">${current.chapitre} · ${current.source}</div><h2>${current.question}</h2><div class=\"choices\">${current.choix.map((c,i)=>`<button class=\"choice\" data-i=\"${i}\">${c}</button>`).join('')}</div><div class=\"exp hidden\"></div>`;card.querySelectorAll('.choice').forEach(b=>b.onclick=()=>answer(+b.dataset.i))}function answer(i){let good=current.bonnesReponses.includes(i);card.querySelectorAll('.choice').forEach((b,k)=>{if(current.bonnesReponses.includes(k))b.classList.add('ok');else if(k===i)b.classList.add('bad')});let e=card.querySelector('.exp');e.classList.remove('hidden');e.textContent=(good?'✅ Bravo ! ':'❌ Pas encore. ')+current.explication}document.getElementById('new').onclick=pick;chap.onchange=pick;pick();</script></body></html>"""

def export_qcm_html(path):
    Path(path).write_text(QCM_HTML, encoding='utf-8')

def _xlsx_col(n):
    s=''
    while n:
        n, r = divmod(n-1, 26)
        s = chr(65+r)+s
    return s

def _xml_escape(x):
    return html.escape(str(x), quote=True)

def export_kahoot_xlsx(path, questions):
    headers = ['Question - max 95 characters','Answer 1 - max 60 characters','Answer 2 - max 60 characters','Answer 3 - max 60 characters','Answer 4 - max 60 characters','Time limit (sec) - 5,10,20,30,60,90 or 120 secs','Correct answer(s) - choose at least one']
    rows = [headers]
    for q in questions:
        choix = list(q['choix'])[:4] + ['']*4
        good = ','.join(str(i+1) for i in q.get('bonnesReponses',[0]))
        rows.append([q['question'][:95], choix[0][:60], choix[1][:60], choix[2][:60], choix[3][:60], int(q.get('temps',20)), good])
    def cell(r,c,v):
        ref=f'{_xlsx_col(c)}{r}'
        if isinstance(v,(int,float)):
            return f'<c r="{ref}"><v>{v}</v></c>'
        return f'<c r="{ref}" t="inlineStr"><is><t>{_xml_escape(v)}</t></is></c>'
    sheet_rows=[]
    for ri,row in enumerate(rows,1):
        sheet_rows.append(f'<row r="{ri}">' + ''.join(cell(ri,ci,v) for ci,v in enumerate(row,1)) + '</row>')
    sheet_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols><col min="1" max="1" width="38" customWidth="1"/><col min="2" max="5" width="20" customWidth="1"/><col min="6" max="7" width="18" customWidth="1"/></cols><sheetData>' + ''.join(sheet_rows) + '</sheetData></worksheet>'
    content_types = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'
    rels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'
    wbxml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Quiz template" sheetId="1" r:id="rId1"/></sheets></workbook>'
    wbrels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'
    p=Path(path); p.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(p, 'w', zipfile.ZIP_DEFLATED) as z:
        z.writestr('[Content_Types].xml', content_types)
        z.writestr('_rels/.rels', rels)
        z.writestr('xl/workbook.xml', wbxml)
        z.writestr('xl/_rels/workbook.xml.rels', wbrels)
        z.writestr('xl/worksheets/sheet1.xml', sheet_xml)

# ============================================================ MAIN
def main():
    for _s in (sys.stdout, sys.stderr):
        try: _s.reconfigure(encoding="utf-8", errors="replace")
        except Exception: pass
    ap = argparse.ArgumentParser()
    ap.add_argument("source")
    ap.add_argument("--mode", choices=["prof","eleve","both"], default="both")
    ap.add_argument("--police", choices=["atkinson","opensans","opendyslexic"], default="atkinson")
    ap.add_argument("--taille", type=float, default=11)
    ap.add_argument("--interligne", type=float, default=1.45)
    ap.add_argument("--couleur", choices=["couleur","nb"], default="couleur")
    ap.add_argument("--html", action="store_true")
    ap.add_argument("--builder", action="store_true", help="générer le sélecteur HTML interactif")
    ap.add_argument("--pont", default=None, help="pont-livret JSON : objectifs visés + grille auto")
    ap.add_argument("--exomap", default=None, help="JSON {code: url} : colonne QR MathALÉA")
    ap.add_argument("--out", default="/home/claude/out")
    ap.add_argument("--export-qcm", default=None, help="écrire/mettre à jour questions.js avec les QCM générés depuis :::mathalea")
    ap.add_argument("--export-kahoot", default=None, help="exporter un .xlsx importable dans Kahoot")
    ap.add_argument("--qcm-html", default=None, help="générer une page qcm-4eme.html qui lit questions.js")
    ap.add_argument("--qcm-par-lien", type=int, default=6, help="nombre de questions générées par lien MathALÉA")
    ap.add_argument("--hub-url", default="", help="URL unique de la page du chapitre (remplace les QR MathALÉA multiples dans le livret)")
    args = ap.parse_args()

    global PONT, EXOMAP, HUB_URL
    HUB_URL = args.hub_url.strip()
    if args.pont:
        pj = json.loads(Path(args.pont).read_text(encoding="utf-8"))
        PONT = {s["code"]: s for s in pj.get("sequences", [])}
        print(f"  · pont-livret : {len(PONT)} chapitre(s) avec objectifs")
    if args.exomap:
        EXOMAP = json.loads(Path(args.exomap).read_text(encoding="utf-8"))
    src = load_source(args.source)
    blocks = parse(src)
    _cov0, _chaps0 = split_chapters(blocks)
    foot_left = "Mathématiques · Mme Le Guern"
    if _chaps0:
        _h = _chaps0[0]["header"]
        foot_left = f"Mathématiques · {_h[0]} · Mme Le Guern · {_h[2]}"
    outdir = Path(args.out); outdir.mkdir(parents=True, exist_ok=True)
    stem = Path(args.source).stem

    if args.export_qcm or args.export_kahoot or args.qcm_html:
        qcm = generate_qcm_from_mathalea(blocks, per_link=args.qcm_par_lien)
        if args.export_qcm:
            export_questions_js(args.export_qcm, qcm)
            print(f"  ✓ QCM JS : {args.export_qcm} ({len(qcm)} questions)")
        if args.export_kahoot:
            export_kahoot_xlsx(args.export_kahoot, qcm)
            print(f"  ✓ Kahoot XLSX : {args.export_kahoot} ({len(qcm)} questions)")
        if args.qcm_html:
            export_qcm_html(args.qcm_html)
            print(f"  ✓ Page QCM : {args.qcm_html}")

    if args.builder:
        cover, _ = split_chapters(blocks)
        print(f"[{stem}] sélecteur HTML")
        build_builder(blocks, outdir, stem, cover)
        return

    modes = ["prof","eleve"] if args.mode == "both" else [args.mode]
    print(f"[{stem}] {args.police} {args.taille}pt int={args.interligne} {args.couleur}" + (" +html" if args.html else ""))
    def _uniq(p):
        if not p.exists(): return p
        i = 1
        while True:
            cand = p.with_name(f"{p.stem} ({i}){p.suffix}")
            if not cand.exists(): return cand
            i += 1
    for m in modes:
        body = render(blocks, m)
        suffix = f"{m}_{args.police}_{int(args.taille)}pt_{args.couleur}"
        pdf = _uniq(outdir / f"{stem}__{suffix}.pdf")
        HTML(string=html_doc(body, build_print_css(args.police, args.taille, args.interligne, args.couleur, foot_left))).write_pdf(str(pdf))
        print(f"  ✓ {pdf.name}")
        if args.html:
            webfile = _uniq(outdir / f"{stem}__{m}_web.html")
            webfile.write_text(html_doc(body, build_web_css(args.police), web=True), encoding="utf-8")
            print(f"  ✓ {webfile.name}")


